@Component
@RequiredArgsConstructor
public class LocalUserJwtAuthenticationConverter implements Converter<Jwt, UsernamePasswordAuthenticationToken> {

    private final UserDetailsService userDetailsService;
    private final UserRepository userRepository;
    private static final Logger logger = LoggerFactory.getLogger(LocalUserJwtAuthenticationConverter.class);

    @Override
    public UsernamePasswordAuthenticationToken convert(Jwt jwt) {
        logger.info("=== CONVERSION JWT UTILISATEUR ===");

        String email = jwt.getClaimAsString("email");
        if (email == null) {
            email = jwt.getClaimAsString("preferred_username");
        }

        logger.info("Email extrait du JWT: {}", email);
        logger.info("Tous les claims: {}", jwt.getClaims());

        UserDetails userDetails = null;

        try {
            // Essayer de charger l'utilisateur existant
            userDetails = userDetailsService.loadUserByUsername(email);
            logger.info("Utilisateur trouvé en BDD: {}", email);
        } catch (UsernameNotFoundException e) {
            logger.info("Utilisateur non trouvé en BDD, création automatique: {}", email);

            // Créer l'utilisateur automatiquement
            User newUser = new User();
            newUser.setEmail(email);
            newUser.setName(jwt.getClaimAsString("name"));
            newUser.setUsername(email);
            newUser.setPassword(""); // Pas de mot de passe local

            // Extraire le rôle depuis Keycloak
            var realmAccess = jwt.getClaimAsMap("realm_access");
            if (realmAccess != null && realmAccess.containsKey("roles")) {
                List<String> roles = (List<String>) realmAccess.get("roles");
                if (!roles.isEmpty()) {
                    // Mapper le rôle Keycloak vers votre rôle
                    String role = roles.get(0).toUpperCase();
                    newUser.setRole(mapKeycloakRoleToLocalRole(role));
                }
            }

            userRepository.save(newUser);
            logger.info("Utilisateur créé avec succès: {}", email);

            // Recharger l'utilisateur
            userDetails = userDetailsService.loadUserByUsername(email);
        }

        return new UsernamePasswordAuthenticationToken(
                userDetails,
                jwt,
                userDetails.getAuthorities()
        );
    }

