        // Adaptez selon vos besoins
        switch(keycloakRole) {
            case "DOCTOR": return "DOCTOR";
            case "PATIENT": return "PATIENT";
            case "CAREGIVER": return "CAREGIVER";
            default: return "PATIENT";
